@@ -54,9 +54,9 @@
 function loop(t){let dt=Math.min(.04,(t-last)/1000||0);last=t;if(!paused)step(dt);draw();requestAnimationFrame(loop)}
 function pop(x,y,color,n=8){for(let i=0;i<n;i++)particles.push({x,y,vx:(Math.random()-.5)*140,vy:-Math.random()*160,life:.45+Math.random()*.4,max:.8,color})}
 function say(text){const el=document.getElementById('toast');el.textContent=text;el.classList.add('show');toastTimer=2.2}
 function addXP(n){xp+=n;while(xp>=100){xp-=100;level++;hp=Math.min(100,hp+20);say(`Naik level! Sekarang level ${level} ✦`)}updateUI()}
-function updateUI(){document.getElementById('healthNum').textContent=Math.max(0,hp);let hearts=document.getElementById('hearts');hearts.innerHTML='';for(let i=0;i<5;i++){let d=document.createElement('span');d.className='heart-unit';let f=document.createElement('i');f.style.width=`${clamp((hp-i*20)/20*100,0,100)}%`;d.appendChild(f);hearts.appendChild(d)}document.getElementById('xpText').textContent=`${xp} / 100 XP`;document.getElementById('xpbar').style.width=`${xp}%`;document.getElementById('level').textContent=`Lv. ${level}`;let items=Object.entries(inv).filter(([,n])=>n>0);if(crafted)items.push(['sword',1]);document.getElementById('bagCount').textContent=`${items.length}/12`;document.getElementById('bag').innerHTML='';let keysIn=['wood','copper','stone','slime','potion','sword'];keysIn.forEach((key,i)=>{let count=key==='sword'?(crafted?1:0):inv[key];let slot=document.createElement('button');slot.className='slot'+(selected===i?' active':'');slot.innerHTML=count?`<span class="key">${i+1}</span><span class="item-icon">${itemInfo[key].icon}</span><span class="count">${count}</span>`:`<span class="key">${i+1}</span>`;slot.title=itemInfo[key].name;slot.onclick=()=>{selected=i;updateUI()};document.getElementById('bag').appendChild(slot)});document.getElementById('craftSword').disabled=crafted||inv.copper<3||inv.wood<2;document.getElementById('craftPotion').disabled=inv.slime<2;let copper=Math.min(6,inv.copper),kills=Math.min(3,slimeKills);document.getElementById('questLabel').textContent=`Tembaga ${copper}/6 · Slime ${kills}/3`;document.getElementById('questBar').style.width=`${(copper/6+kills/3)*50}%`;if(copper>=6&&kills>=3){document.getElementById('questTitle').textContent='Bahan terkumpul!';document.getElementById('questText').textContent='Buat pedang tembaga di meja kerajinan, lalu jelajahi gua yang lebih dalam.'}}
+function updateUI(){document.getElementById('healthNum').textContent=Math.max(0,hp);let hearts=document.getElementById('hearts');hearts.innerHTML='';for(let i=0;i<5;i++){let d=document.createElement('span');d.className='heart-unit';let f=document.createElement('i');f.style.width=`${clamp((hp-i*20)/20*100,0,100)}%`;d.appendChild(f);hearts.appendChild(d)}document.getElementById('xpText').textContent=`${xp} / 100 XP`;document.getElementById('xpbar').style.width=`${xp}%`;document.getElementById('level').textContent=`Lv. ${level}`;let items=Object.entries(inv).filter(([,n])=>n>0);if(crafted)items.push(['sword',1]);document.getElementById('bagCount').textContent=`${items.length}/12`;document.getElementById('bag').innerHTML='';let keysIn=['wood','copper','stone','slime','potion','sword'];keysIn.forEach((key,i)=>{let count=key==='sword'?(crafted?1:0):inv[key];let slot=document.createElement('button');slot.className='slot'+(selected===i?' active':'');slot.innerHTML=count?`<span class="key">${i+1}</span><span class="item-icon">${itemInfo[key].icon}</span><span class="count">${count}</span>`:`<span class="key">${i+1}</span>`;slot.title=itemInfo[key].name;slot.onclick=()=>{selected=i;if(key==='potion'&&inv.potion>0)drink();else updateUI()};document.getElementById('bag').appendChild(slot)});document.getElementById('craftSword').disabled=crafted||inv.copper<3||inv.wood<2;document.getElementById('craftPotion').disabled=inv.slime<2;let copper=Math.min(6,inv.copper),kills=Math.min(3,slimeKills);document.getElementById('questLabel').textContent=`Tembaga ${copper}/6 · Slime ${kills}/3`;document.getElementById('questBar').style.width=`${(copper/6+kills/3)*50}%`;if(copper>=6&&kills>=3){document.getElementById('questTitle').textContent='Bahan terkumpul!';document.getElementById('questText').textContent='Buat pedang tembaga di meja kerajinan, lalu jelajahi gua yang lebih dalam.'}}
 function mineAt(clientX,clientY){const rect=canvas.getBoundingClientRect(),tx=Math.floor((clientX-rect.left+cameraX)/TILE),ty=Math.floor((clientY-rect.top+cameraY)/TILE),t=getTile(tx,ty);if(!t)return;let cx=(tx+.5)*TILE,cy=(ty+.5)*TILE;if(Math.hypot(cx-(player.x+player.w/2),cy-(player.y+player.h/2))>TILE*5){say('Blok itu terlalu jauh.');return}if(t==='tree'){inv.wood++;setTile(tx,ty,null);for(let y=ty-1;y>=0&&getTile(tx,y)==='tree';y--)setTile(tx,y,null);pop(cx,cy,'#9b7955',10);say('+1 kayu')}else if(t==='stone'||t==='dirt'||t==='grass'){setTile(tx,ty,null);if(ores.has(tileKey(tx,ty))){ores.delete(tileKey(tx,ty));inv.copper++;say('+1 tembaga ✦')}else if(t==='stone'){inv.stone++;say('+1 batu')}pop(cx,cy,t==='stone'?'#9ba79d':'#ac8059',8)}else return;addXP(5);updateUI()}
 function attack(){player.attack=.25;let hit=false;for(const e of enemies){if(!e.alive)continue;let dx=e.x-player.x,dist=Math.hypot(dx,e.y-player.y);if(dist<76&&Math.sign(dx||1)===player.face){e.hp-=crafted?42:18;hit=true;pop(e.x+e.w/2,e.y+5,'#a2d68c',6);if(e.hp<=0){e.alive=false;slimeKills++;inv.slime++;addXP(26);say('Slime dikalahkan! +lendir · +26 XP')}else say('Kena! Slime terluka')} }if(!hit)say('Dekati slime untuk menyerang.');updateUI()}
 function craft(type){if(type==='sword'){if(crafted||inv.copper<3||inv.wood<2)return;inv.copper-=3;inv.wood-=2;crafted=true;say('Pedang tembaga ditempa! Serangan meningkat.');addXP(30)}else{if(inv.slime<2)return;inv.slime-=2;inv.potion++;say('Potion kecil dibuat. Pilih slot dan ketuk untuk minum.')}updateUI()}
 function drink(){if(inv.potion>0&&hp<100){inv.potion--;hp=Math.min(100,hp+30);say('Memulihkan 30 HP.');updateUI()}else if(hp>=100)say('HP sudah penuh.')}
